#include <algorithm>
using namespace std;

using ll = long long;

constexpr int ARRAY_SIZE = 10000005;
ll b[ARRAY_SIZE];

void fillSquares() {
    for (ll i = 1; i * i < ARRAY_SIZE; ++i) {
        const ll square = i * i;
        for (ll j = square; j < ARRAY_SIZE; j += square) {
            b[j] = square;
        }
    }
}

ll answer(ll a, ll n) {
    ll ans = 0;
    for (ll i = a; i < a + n; ++i) {
        ans += i / b[i];
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, n;
    cin >> a >> n;

    fillSquares();
    cout << answer(a, n);

    return 0;
}

